Q: How Can I PAUSE or RESUME a async task using a button in flutter? A: <blockquote>
<blockquote>
<p>I want the user to control the UI with a single button behave as START, PAUSE and RESUME. Can we Use normal function To implement this functionality?</p>
</blockquote>
</blockquote>
<p>Perhaps this simple example will help at least a little?</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:multitasking/misc/pause.dart';
import 'package:multitasking/multitasking.dart';

void main(List&lt;String&gt; args) {
  final cts = CancellationTokenSource();
  final pts = PauseTokenSource();

  _showImages(const Duration(seconds: 2), cts.token, pts.token);

  Timer(const Duration(milliseconds: 5500), () {
    _message('Pause');
    pts.pause();
  });

  Timer(const Duration(milliseconds: 8000), () {
    _message('Resume');
    pts.resume();
  });

  Timer(const Duration(seconds: 14), () {
    _message('Pause');
    pts.pause();
  });

  Timer(const Duration(seconds: 15), () {
    _message('Cancel (abort)');
    cts.cancel();
  });
}

final _sw = Stopwatch()..start();

void _message(String text) {
  print('${_sw.elapsedMilliseconds.sec}: $text');
}

Future&lt;void&gt; _showImages(
    Duration duration, CancellationToken cancel, PauseToken pause) async {
  var completer = Completer&lt;void&gt;()..complete();
  var timer = Timer(const Duration(), () {});
  Future&lt;void&gt; run() async {
    var i = 0;
    while (true) {
      cancel.throwIfCancelled();
      _message('image_$i');
      i++;
      completer = Completer&lt;void&gt;();
      timer = Timer(duration, () {
        if (!completer.isCompleted) {
          completer.complete();
        }
      });

      await completer.future;
      await pause.wait(token: cancel);
    }
  }

  try {
    await cancel.runCancellable(() {
      if (!completer.isCompleted) {
        completer.complete();
      }

      timer.cancel();
    }, run);
  } on TaskCanceledError {
    // Ignore
  }

  _message('The end');
}

extension on int {
  String get sec {
    return (this / 1000).toStringAsFixed(2);
  }
}

</code></pre>
